71: /* draw an outlined blob: silhouette + fill + layered shading + highlights */
72: function blob(c,cx,cy,rx,ry,dark,base,light,opts={}) {
73:   // silhouette / contact outline
74:   PX.ell(c,cx,cy,rx+2,ry+2,dark);
75:   // base fill
76:   PX.ell(c,cx,cy,rx,ry,base);
77:   // broad underside shading
78:   PX.ell(c,cx,cy+ry*0.30,rx*0.94,ry*0.60,shiftColor(base,-7,.95,.81));
79:   // mid-body gradient band
80:   PX.ell(c,cx-rx*0.10,cy+ry*0.06,rx*0.78,ry*0.52,shiftColor(base,2,.88,.92));
81:   // warm belly
82:   PX.ell(c,cx-rx*0.05,cy+ry*0.55,rx*0.60,ry*0.30,opts.belly||shiftColor(base,8,.68,1.14));
83:   // top-left key light
84:   PX.ell(c,cx-rx*0.28,cy-ry*0.36,rx*0.52,ry*0.27,light);
85:   PX.ell(c,cx-rx*0.34,cy-ry*0.42,rx*0.30,ry*0.15,'#ffffff');
86:   // dither speckles along the shadow side for a soft pixel gradient
87:   for (let i=0;i<4;i++){
88:     const t=(i+1)/5;
89:     PX.rect(c,Math.round(cx+rx*(.35+t*.4)),Math.round(cy+ry*(.10+t*.45)),1,1,spriteAlpha(dark,.35));
90:   }
91:   if (opts.detail!==false) {
92:     PX.rect(c,Math.round(cx-rx*.34),Math.round(cy+ry*.30),Math.max(2,Math.round(rx*.3)),1,spriteAlpha(light,.30));
93:   }
94: }
