96: function eye(c,x,y,rx,ry,opts={}) {
97:   const look = opts.look == null ? 0.4 : opts.look;
98:   const iris = opts.iris || '#22314a';
99:   // socket + sclera
100:   PX.ell(c,x,y,rx+1.4,ry+1.4,'#17121f');
101:   PX.ell(c,x,y,rx,ry,'#fbfdff');
102:   // iris gradient
103:   PX.ell(c,x+look*rx*.38,y+ry*.06,rx*.70,ry*.78,iris);
104:   PX.ell(c,x+look*rx*.38,y+ry*.16,rx*.46,ry*.52,shiftColor(iris,-18,1.1,.72));
105:   // pupil
106:   PX.ell(c,x+look*rx*.40,y+ry*.14,rx*.23,ry*.34,'#0a0e18');
107:   // catchlights
108:   PX.ell(c,x-rx*.20,y-ry*.30,rx*.34,ry*.30,'#ffffff');
109:   if (opts.pupilShine!==false) PX.ell(c,x+rx*.30,y+ry*.28,rx*.17,ry*.16,'#ffffff');
110:   // brow / upper lid shadow
111:   PX.rect(c,Math.round(x-rx),Math.round(y-ry-1),Math.round(rx*2+1),1,spriteAlpha('#17121f',.32));
112: }
